for f in \""'${simple_files[@]}"; do
  HAP_COMPONENT="$component" perl -0pi -e '"'s/\\n\\@Entry/\\n"'$ENV{HAP_COMPONENT}'"\\@Entry/' \""'$f"
  perl -0pi -e '"'s/Column\\(\\) \\{\\n([ \\t]*)Text\\('\\''N'\\'' \\+ item\\)\\.fontSize\\(12\\)\\.height\\('\\''16'\\''\\)\\n[ \\t]*\\}/Column() {\\n"'$1WaterFlowItemContent({ item: item })'"\\n"'$1}.width('"'\\''100%'\\'')/g' \""'$f"
done
start_file=entry/src/main/ets/MainAbility/pages/waterFlowCallback/waterFlowStart1.ets
start_component="@Reusable
@Component
struct WaterFlowItemContent {
