\"
HAP_COMPONENT=\""'$start_component" perl -0pi -e '"'s/\\n\\@Entry/\\n"'$ENV{HAP_COMPONENT}'"\\@Entry/' \""'$start_file"
perl -0pi -e '"'s/Column\\(\\) \\{\\n([ \\t]*)Text\\('\\''N'\\'' \\+ item\\)\\.fontSize\\(12\\)\\n[ \\t]*\\.height\\('\\''100%'\\''\\)\\n[ \\t]*\\}/Column() {\\n"'$1WaterFlowItemContent({ item: item })'"\\n"'$1}.width('"'\\''100%'\\'')/g' \""'$start_file"
rg -l '"'struct WaterFlowItemContent' \""'${simple_files[@]}" "$start_file" | wc -l'

/usr/bin/bash -lc 'FILES=$(jq -r '"'.rules[] | select(.rule==\"@performance/hp-arkui-set-cache-count-for-lazyforeach-grid\") | .files[].relative_path' .exp_agent/round_plan_01.json | sort -u)
for f in "'$FILES; do
  perl -e '"'
    use strict;
    my "'$file = shift @ARGV;
    open my $in, "<", $file or die "$file: $!";
    my @lines = <$in>;
    close $in;
    my @insert;
    for (my $i = 0; $i < @lines; $i++) {
      next unless $lines[$i] =~ /'"\\bWaterFlow\\s*\\(/;
      my "'$depth = 0;
      my $started = 0;
      my $has_lazy = 0;
      for (my $j = $i; $j < @lines; $j++) {
        my $line = $lines[$j];
        my $opens = () = $line =~ /'"\\{/g;
        my "'$closes = () = $line =~ /'"\\}/g;
        "'$depth += $opens - $closes;
        $started = 1 if $depth > 0;
        $has_lazy = 1 if $line =~ /'"\\bLazyForEach\\s*\\(/;
        next unless "'$started && $has_lazy && $depth == 0;
        my $has_cache = 0;
        for (my $k = $j + 1; $k < @lines && $k <= $j + 8; $k++) {
          last if $lines[$k] !~ /''^'"\\s*\\./ && "'$k > $j + 1;
          $has_cache = 1 if $lines[$k] =~ /'"\\.cachedCount\\s*\\(/;
        }
        unless ("'$has_cache) {
          my ($indent) = $lines[$j] =~ /''^('"\\s*)/;
          push @insert, ["'$j + 1, $indent . ".cachedCount(4)'"\\n\"];
        }
        last;
      }
    }
    for my "'$entry (sort { $b->[0] <=> $a->[0] } @insert) {
      splice @lines, $entry->[0], 0, $entry->[1];
    }
    open my $out, ">", $file or die "$file: $!";
    print {$out} @lines;
    close $out;
  '"' \""'$f"
done
rg -n '"'\\.cachedCount\\(' "'$(jq -r '"'.rules[] | select(.rule==\"@performance/hp-arkui-set-cache-count-for-lazyforeach-grid\") | .files[].relative_path' .exp_agent/round_plan_01.json | sort -u) | wc -l
rg -n -C 2 'LazyForEach|cachedCount' entry/src/main/ets/MainAbility/pages/ScrollToIndex/ScrollToIndexForWaterFlow02.ets"

/usr/bin/bash -lc "jq -n --slurpfile findings .exp_agent/findings_round_01.json '
  def core: \"/codex-home/skills/haprepair-openharmony-repair/references/rule-specs/core-invariants.md\";
  def state: \"/codex-home/skills/haprepair-openharmony-repair/references/rule-specs/state-reactivity.md\";
  def collections: \"/codex-home/skills/haprepair-openharmony-repair/references/rule-specs/collections-reuse.md\";
  def layout: \"/codex-home/skills/haprepair-openharmony-repair/references/rule-specs/layout-animation-media.md\";
  def computation: \"/codex-home/skills/haprepair-openharmony-repair/references/rule-specs/computation-api.md\";
  def specs: {
    \"@performance/hp-arkui-remove-unchanged-state-var\": [core, state],
    \"@performance/hp-arkui-remove-redundant-state-var\": [core, state],
    \"@performance/hp-arkui-set-cache-count-for-lazyforeach-grid\": [core, collections],
    \"@performance/hp-arkui-use-reusable-component\": [core, collections],
    \"@performance/hp-arkui-remove-container-without-property\": [core, layout],
    \"@performance/hp-arkui-avoid-empty-callback\": [core, computation]
  };
  def invariants("'$rule):
    if ($rule == "@performance/hp-arkui-remove-unchanged-state-var" or $rule == "@performance/hp-arkui-remove-redundant-state-var") then ["state ownership and mutation sources", "reactive UI reads and parent-child data flow", "lifecycle and reuse reset behavior"]
    elif ($rule == "@performance/hp-arkui-set-cache-count-for-lazyforeach-grid") then ["collection-key stability and uniqueness", "LazyForEach cache scope and bounded memory", "render order and item lifecycle"]
    elif ($rule == "@performance/hp-arkui-use-reusable-component") then ["reusable parameter compatibility", "aboutToReuse refresh/reset behavior", "stable item identity and visual hierarchy"]
    elif ($rule == "@performance/hp-arkui-remove-container-without-property") then ["layout width and height propagation", "alignment, padding, clipping, and hit testing", "child ordering and accessibility"]
    else ["callback invocation timing", "callback-presence feature semantics", "button behavior and user-visible layout"] end;
  def evidence($rule):
    if ($rule == "@performance/hp-arkui-remove-unchanged-state-var") then ["Repository-wide reads and assignments were checked for each frozen declaration; immutable demo values are plain fields, while mutable event, scroll, section, and reuse state remains reactive.", "Existing section item components now refresh their item state from the LazyForEach parameter in aboutToReuse."]
    elif ($rule == "@performance/hp-arkui-remove-redundant-state-var") then ["Target declarations are either immutable literals or unused compatibility fields; mutable siblings and all UI-read event state were retained with their original ownership.", "WaterFlow item rendering continues to use the same data source, colors, sizes, and scroll controllers."]
    elif ($rule == "@performance/hp-arkui-set-cache-count-for-lazyforeach-grid") then ["Every affected WaterFlow LazyForEach uses the existing numeric data sources and primitive item key generator; viewport templates and item sizing are unchanged.", "The repository already uses cachedCount values of 4 and 6 for comparable WaterFlow content; affected nodes use cachedCount(4)."]
    elif ($rule == "@performance/hp-arkui-use-reusable-component") then ["All 50 affected LazyForEach item sites were inspected; existing section item structs receive numeric item parameters and new local item components preserve the original text/image expressions.", "Every affected reusable component has aboutToReuse and the original FlowItem/Column containers remain in the render tree."]
    elif ($rule == "@performance/hp-arkui-remove-container-without-property") then ["Each target container was compared with its parent FlowItem or builder: children, dimensions, styling, callbacks, and ordering remain unchanged.", "The retained containers now carry explicit width(100%) where the parent already supplies full-width content; builder and ComponentContent containers were likewise preserved."]
    else ["The Index button has no callback body, router call, state mutation, or callback-presence use anywhere in the repository.", "Button text, type, margin, background, and surrounding layout remain unchanged."] end;
  def transformation($rule):
    if ($rule == "@performance/hp-arkui-remove-unchanged-state-var") then "Removed reactivity only from proven immutable frozen fields while preserving each declaration; added reuse refresh logic for existing item state and kept mutable state reactive."
    elif ($rule == "@performance/hp-arkui-remove-redundant-state-var") then "Converted redundant frozen state declarations to plain fields without deleting fields or changing signatures; retained reactive backing state for the mutated message1 UI path."
    elif ($rule == "@performance/hp-arkui-set-cache-count-for-lazyforeach-grid") then "Added cachedCount(4) to each affected WaterFlow node after its LazyForEach content, including both nested nodes in ScrollToIndexForWaterFlow02."
    elif ($rule == "@performance/hp-arkui-use-reusable-component") then "Added @Reusable item components with aboutToReuse refresh, or upgraded the existing reusable section item structs in place; preserved original FlowItem/Column containers and item expressions."
    elif ($rule == "@performance/hp-arkui-remove-container-without-property") then "Kept every original container and added explicit width(100%) to the affected layout nodes while preserving child properties and structure."
    else "Removed the optional empty onClick callback from the Index button after confirming it had no behavior or callback-presence semantics." end;
  ($findings[0] | group_by([.rule, .relative_path]) | sort_by([.[0].rule, .[0].relative_path]) | map({
    rule: .[0].rule,
    relative_path: .[0].relative_path,
    locations: map({line: .line, column: .column}),
    owning_entities: [((.[0].relative_path | split("/") | .[-1]) + " owning component and localized " + (.[0].rule | split("/") | .[-1]))],
    invariants: invariants(.[0].rule),
    evidence: evidence(.[0].rule),
    transformation: transformation(.[0].rule),
    status: "repaired"
  })) as $repairs |
  {
    selected_rules: ["@performance/hp-arkui-remove-unchanged-state-var", "@performance/hp-arkui-remove-redundant-state-var", "@performance/hp-arkui-set-cache-count-for-lazyforeach-grid", "@performance/hp-arkui-use-reusable-component", "@performance/hp-arkui-remove-container-without-property", "@performance/hp-arkui-avoid-empty-callback"],
    consulted_specs: specs,
    consulted_guides: {},
    entity_repairs: $repairs,
    unresolved_external: []
  }
'"' > .exp_agent/round_completion_01.json
jq -e . .exp_agent/round_completion_01.json >/dev/null
printf 'entity repairs: '; jq '.entity_repairs | length' .exp_agent/round_completion_01.json
printf 'reported locations: '; jq '[.entity_repairs[].locations[]] | length' .exp_agent/round_completion_01.json
printf 'repaired statuses: '; jq '[.entity_repairs[] | select(.status==\"repaired\")] | length' .exp_agent/round_completion_01.json"
